# ruff: noqa: E501
"""Report section "SA2.4 y SA2.7 vs. baseline" (Spanish prose, tables generated by code)."""

import numpy as np
import pandas as pd

from firecal.stages.harmonize.evaluate import MAIN_PAIRS, FoldOut, coverage_table, score_table
from firecal.stages.harmonize.metrics import wape
from firecal.stages.harmonize.ml import ML_METHODS, MLResult
from firecal.stages.harmonize.ml_criterion import (
    BOOT_LEVEL,
    BOOT_SEED,
    N_BOOT,
    Verdict,
    evaluate_criterion,
)

CANDIDATES = ("lgb_cell", "lgb_block")
DIRECTION = {
    "viirs_to_modis": "SA2.4: VIIRS (S-NPP) -> MODIS-equivalente",
    "modis_to_viirs": "SA2.7: MODIS -> VIIRS-equivalente (serie inversa)",
}
NAMES = {"sf": "SA2.2 factor"} | ML_METHODS


def _fmt():
    from firecal.stages.harmonize.report import md_table, num, pct

    return md_table, num, pct


def verdicts(ml: MLResult, sf_folds: list[FoldOut]) -> dict[tuple[str, str], Verdict]:
    allml = [f for fs in ml.folds.values() for f in fs]
    out = {}
    for pair in MAIN_PAIRS:
        for method in CANDIDATES:
            out[pair, method] = evaluate_criterion(sf_folds, allml, pair, method)
    return out


def _years(folds, pair, scheme, method) -> dict[int, FoldOut]:
    return {f.test_year: f for f in folds if (f.pair, f.scheme, f.method) == (pair, scheme, method)}


def _pooled(fs: list[FoldOut], years) -> tuple[np.ndarray, np.ndarray]:
    return (
        np.concatenate([fs[y].obs.ravel() for y in years]),
        np.concatenate([fs[y].pred.ravel() for y in years]),
    )


def zero_tree_check(allf: list[FoldOut], pair: str) -> list[dict]:
    """Zero-tree (offset only) vs SA2.2 block totals pooled over the leave-one-year-out test years."""
    sf = _years(allf, pair, "loyo", "sf")
    rows = []
    for method in ("zero_cell", "zero_block"):
        z = _years(allf, pair, "loyo", method)
        years = sorted(set(z) & set(sf))
        if not years:
            continue
        zb = sum(z[y].pred.sum(axis=0) for y in years)
        sb = sum(sf[y].pred.sum(axis=0) for y in years)
        rel = np.abs(zb - sb) / np.where(sb > 0, sb, np.nan)
        big = sb >= 1000
        o, p = _pooled(sf, years)
        _, pz = _pooled(z, years)
        rows.append(
            {
                "method": method,
                "total_ratio": float(zb.sum() / sb.sum()),
                "max_rel_big": float(np.nanmax(rel[big])) if big.any() else float("nan"),
                "n_blocks": int((sb > 0).sum()),
                "n_over_1": int(np.nansum(rel > 0.01)),
                "n_big": int(big.sum()),
                "wape_zero": wape(o, pz),
                "wape_sf": wape(o, p),
            }
        )
    return rows


def ml_section(ml: MLResult, sf_folds: list[FoldOut]) -> list[str]:
    md_table, num, pct = _fmt()
    allml = [f for fs in ml.folds.values() for f in fs]
    allf = sf_folds + allml
    scores = score_table(allf)
    ver = verdicts(ml, sf_folds)

    def row(pair, scheme, method, year, level):
        s = scores[
            (scores["pair"] == pair)
            & (scores["scheme"] == scheme)
            & (scores["method"] == method)
            & (scores["test_year"].astype(str) == str(year))
            & (scores["level"] == level)
        ]
        return s.iloc[0] if len(s) else None

    L = ["## SA2.4 y SA2.7 vs. baseline", ""]
    L += [
        "LightGBM sobre el factor de escala de SA2.2 (el factor entra como offset: `init_score = log(f_bloque x fuente + eps)`), "
        "con las mismas métricas, los mismos pliegues (año afuera con 6 meses de separación y origen móvil) y la misma "
        "suma a bloque-mes y bloque-año que SA2.2. Todo es retrospectivo. El criterio de publicación estaba fijado en "
        "`plan/02-harmonization.md` antes de la corrida y no se tocó después de ver resultados.",
        "",
        "### Qué se corrió",
        "",
        "- **Modelo de celda** (candidato principal): filas de celda de 0,1° x mes x día/noche donde la **fuente** está activa en la celda o en su 3x3 "
        '(el diseño decía "algún sensor activo"; con el objetivo observado en test el conjunto de filas filtraría el objetivo y, entrenando solo con '
        "filas de objetivo activo, sesgaría hacia arriba las filas sin fuente; el cambio es una decisión de implementación, no del criterio). Las "
        "detecciones del objetivo en celdas-mes sin fuente en su 3x3 quedan fuera de alcance (como el origen = 0 de SA2.2): "
        + ", ".join(
            f"{DIRECTION[p].split(':')[0]} {pct(ml.meta[p]['unreachable_share'])} de las detecciones del objetivo ({ml.meta[p]['cell_rows']:,} filas)"
            for p in MAIN_PAIRS
            if p in ml.meta
        )
        + ".",
        "- **Variables** (todas de la fuente, conocidas al predecir): conteo, FRP, FRP por detección, conteo del otro período del día (día/noche), proporción "
        "de día/noche, es-noche, conteo en 3x3, total de la fuente en el bloque-mes y mes del año. Ablaciones: con proporción Terra/Aqua (solo MODIS como fuente: "
        "terra y aqua por separado, FRP por satélite y proporción de Terra; en VIIRS -> MODIS no existe, queda igual) y con lat/lon. "
        "El candidato principal es el modelo base sin proporción Terra/Aqua y sin lat/lon; las ablaciones no son candidatas.",
        "- **Offset:** fuente suavizada (3x3 en filas sin fuente) y reescalada por bloque-mes-día/noche para conservar el total de la fuente: sin ese "
        "reescalado el suavizado agrega masa y con cero árboles no se reproduciría SA2.2. Factores de las filas de entrenamiento: fuera de muestra "
        "(año afuera interno, con separación); los de las filas de test: ajustados en el entrenamiento externo.",
        "- **Modelo bloque-mes:** mismas ideas sobre filas bloque-mes x día/noche (muy regularizado, 3-7 hojas), segundo candidato.",
        "- **Objetivo y selección:** Poisson (Tweedie 1,2 solo en la grilla del modelo bloque-mes). Hiperparámetros por WAPE bloque-mes con año afuera interno dentro de "
        "cada entrenamiento externo; aprendizaje 0,1 en la celda y 0,05 en el bloque, `num_threads` = 2, semilla fija, `deterministic`.",
        f"- **Grilla (reducida por tiempo):** celda: una estructura ({ml.cell_grid[0].num_leaves} hojas, mínimo {ml.cell_grid[0].min_data} filas por hoja, L2 {ml.cell_grid[0].l2:g}) con "
        f"{'/'.join(str(i) for i in ml.cell_grid[0].iters)} árboles a elegir; bloque-mes: {len(ml.block_grid)} estructuras x "
        f"{'/'.join(str(i) for i in ml.block_grid[0].iters)} árboles. El diseño de evaluación (anidado, mismos pliegues) no se redujo. "
        "Las ablaciones reutilizan la configuración que eligió el modelo de celda base en el mismo pliegue.",
        "- **Intervalos:** esquema conformal anidado de SA2.2 (`intervals.py`) sobre las predicciones puntuales de LightGBM (residuos fuera de muestra de la "
        "configuración elegida); sin regresión cuantílica de LightGBM (diagnóstico opcional, no corrido).",
        f"- **Tiempo y memoria:** {ml.seconds / 60:.1f} min de reloj para esta parte, un proceso por sentido (2 hilos cada uno); memoria máxima sumada "
        f"(PSS de los procesos) {ml.peak_mb:.0f} MB.",
        "",
    ]

    # --- Verdict ---
    L += ["### Criterio de publicación y veredicto", ""]
    L += [
        "Se publica LightGBM en un sentido solo si el candidato cumple las siete condiciones (la 6 solo en SA2.7): "
        "1) WAPE bloque-mes con año afuera al menos 1 punto menor que SA2.2 y bloque-año no mayor; 2) menor WAPE bloque-mes en al menos 10 de 14 años de test; "
        "3) mejora del mismo signo con origen móvil; 4) |sesgo| total no peor que el de SA2.2 + 0,5 puntos y el peor año no peor; "
        "5) devianza de Poisson bloque-mes no peor; 6) cobertura conformal bloque-mes 80 +/- 5 % y ancho relativo no mayor; "
        f"7) el intervalo bootstrap pareado (años y bloques remuestreados por separado, {N_BOOT} remuestras, semilla {BOOT_SEED}, percentiles al {BOOT_LEVEL * 100:.0f} %) "
        'de la diferencia de WAPE bloque-mes excluye cero. Interpretaciones fijadas antes de la corrida: el "peor año" es un año de test del año afuera; '
        'la cobertura y el ancho son los de bloque-mes (la de bloque-año se informa, no es condición); "excluye cero" exige límite superior < 0. '
        "El veredicto del sentido es el del candidato principal (celda); el modelo bloque-mes tiene el suyo, por separado.",
        "",
    ]
    for pair in MAIN_PAIRS:
        for method in CANDIDATES:
            v = ver[pair, method]
            tag = "candidato principal" if method == "lgb_cell" else "segundo candidato"
            L.append(f"**{DIRECTION[pair]} - {NAMES[method]} ({tag}): {v.text}.**")
            L.append("")
            L += md_table(
                ["Condición", "Resultado", "Detalle"],
                [[c.name, "cumple" if c.passed else "NO cumple", c.detail] for c in v.conditions],
            )
            L.append("")
    L.append(
        "Veredicto por sentido (candidato principal): "
        + "; ".join(f"{DIRECTION[p].split(':')[0]}: {ver[p, 'lgb_cell'].text}" for p in MAIN_PAIRS)
        + ". Si no supera, se publica SA2.2."
    )
    L.append("")

    for pair in MAIN_PAIRS:
        L += [f"### {DIRECTION[pair]}", ""]
        # headline pooled
        rows = []
        cand_years = sorted(
            set(_years(allf, pair, "loyo", "lgb_cell")) & set(_years(allf, pair, "loyo", "sf"))
        )
        sf_y = _years(allf, pair, "loyo", "sf")
        for method in (
            "sf",
            "lgb_cell",
            "lgb_block",
            "lgb_cell_ta",
            "lgb_cell_ll",
            "zero_cell",
            "zero_block",
        ):
            a = row(pair, "loyo", method, "all", "block-month")
            if a is None:
                continue
            b = row(pair, "loyo", method, "all", "block-year")
            my = _years(allf, pair, "loyo", method)
            ys = sorted(set(my) & set(sf_y))
            won = (
                "-"
                if method == "sf"
                else f"{sum(wape(my[y].obs, my[y].pred) < wape(sf_y[y].obs, sf_y[y].pred) for y in ys)} de {len(ys)}"
            )
            ry, rs = _years(allf, pair, "rolling", method), _years(allf, pair, "rolling", "sf")
            common = sorted(set(ry) & set(rs))
            roll = pct(wape(*_pooled(ry, common))) if common else "-"
            roll_sf = pct(wape(*_pooled(rs, common))) if common and method != "sf" else ""
            rows.append(
                [
                    NAMES[method],
                    pct(a["bias"], True),
                    pct(a["wape"]),
                    pct(b["wape"]),
                    num(a["mae"], 2),
                    num(a["deviance"], 2),
                    won,
                    roll + (f" (SA2.2 {roll_sf})" if roll_sf else ""),
                ]
            )
        L += md_table(
            [
                "Método",
                "Sesgo b-mes",
                "WAPE b-mes",
                "WAPE b-año",
                "MAE b-mes",
                "Devianza b-mes",
                "Años con menor WAPE b-mes que SA2.2",
                "WAPE b-mes origen móvil",
            ],
            rows,
        )
        L += [
            "",
            f"Año afuera, {len(cand_years)} años de test, todos juntos; la columna de origen móvil usa los años que tienen resultado de los dos (el primero con un solo año "
            "de entrenamiento no admite año afuera interno y se omite en LightGBM).",
            "",
        ]
        # per year
        rows = []
        for y in cand_years:
            vals = []
            for method in ("sf", "lgb_cell", "lgb_block"):
                a, b = row(pair, "loyo", method, y, "block-month"), row(pair, "loyo", method, y, "block-year")
                vals.append((a, b))
            rows.append(
                [y]
                + [pct(v[0]["wape"]) for v in vals]
                + [pct(v[1]["wape"]) for v in vals]
                + [pct(v[0]["bias"], True) for v in vals]
                + ["celda" if vals[1][0]["wape"] < vals[0][0]["wape"] else "SA2.2"]
            )
        L += ["Error por año de test (año afuera):", ""]
        L += md_table(
            [
                "Año",
                "WAPE b-mes SA2.2",
                "celda",
                "bloque",
                "WAPE b-año SA2.2",
                "celda",
                "bloque",
                "Sesgo SA2.2",
                "celda",
                "bloque",
                "Menor b-mes (SA2.2 vs celda)",
            ],
            rows,
        )
        L.append("")

        # intervals
        cov_sf = coverage_table(allf, method="sf")
        covs = {m: coverage_table(allf, method=m) for m in CANDIDATES}
        rows = []
        for level in ("block-month", "block-year"):
            for method, tab in (
                ("sf", cov_sf),
                ("lgb_cell", covs["lgb_cell"]),
                ("lgb_block", covs["lgb_block"]),
            ):
                r = tab[
                    (tab["pair"] == pair)
                    & (tab["scheme"] == "loyo")
                    & (tab["interval"] == "conformal")
                    & (tab["level"] == level)
                    & (tab["test_year"].astype(str) == "all")
                ]
                if len(r):
                    r = r.iloc[0]
                    rows.append(
                        [
                            level,
                            NAMES[method],
                            int(r["n"]),
                            pct(r["coverage"]),
                            num(r["rel_width"], 3),
                            pct(r["out_share"]),
                        ]
                    )
        L += ["Intervalos conformales anidados (nominal 80 %, año afuera, filas con fuente > 0):", ""]
        L += md_table(
            ["Nivel", "Método", "n", "Cobertura", "Ancho relativo", "Detecciones fuera de alcance"], rows
        )
        L.append("")

        # zero-tree
        zt = zero_tree_check(allf, pair)
        if zt:
            L += [
                "Verificación de cero árboles (el offset solo debe reproducir los totales por bloque de SA2.2; dentro de ~1 %):",
                "",
            ]
            L += md_table(
                [
                    "Modelo",
                    "Total / total SA2.2",
                    "Máx. dif. relativa por bloque (bloques con >= 1000 predichas)",
                    "Bloques con dif. > 1 %",
                    "WAPE b-mes cero árboles",
                    "WAPE b-mes SA2.2",
                ],
                [
                    [
                        NAMES[z["method"]],
                        num(z["total_ratio"], 4),
                        pct(z["max_rel_big"]),
                        f"{z['n_over_1']} de {z['n_blocks']} (con >= 1000: {z['n_big']})",
                        pct(z["wape_zero"]),
                        pct(z["wape_sf"]),
                    ]
                    for z in zt
                ],
            )
            L.append("")

    # --- config / importance ---
    L += ["### Configuración elegida por año de test (año afuera)", ""]
    rows = []
    for dg in sorted((d for d in ml.diags if d.scheme == "loyo"), key=lambda d: (d.pair, d.test_year)):
        rows.append(
            [
                DIRECTION[dg.pair].split(":")[0],
                dg.test_year,
                f"{dg.cell_cfg} / {dg.cell_iters} árboles",
                f"{dg.block_cfg} / {dg.block_iters} árboles",
            ]
        )
    L += md_table(["Sentido", "Año", "Celda", "Bloque-mes"], rows)
    L += ["", "### Importancia de variables (ganancia, modelo de celda base)", ""]
    L += [
        "Ganancia normalizada a 1 por pliegue y promediada sobre los pliegues con año afuera. Describe qué variables usó el modelo; no es un efecto causal "
        "ni una importancia por permutación.",
        "",
    ]
    for pair in MAIN_PAIRS:
        imp = [d.importance for d in ml.diags if d.pair == pair and d.scheme == "loyo"]
        if not imp:
            continue
        mean = pd.Series({k: np.mean([i[k] for i in imp]) for k in imp[0]}).sort_values(ascending=False)
        L += [f"{DIRECTION[pair]}:", ""]
        L += md_table(["Variable", "Ganancia media"], [[k, pct(v)] for k, v in mean.items()])
        L.append("")
    L += [
        "Notas: la causa de cualquier diferencia entre modelos está **sin verificar**; las tablas solo describen. Los resultados valen para Argentina, 2012-02 a 2025-12 "
        "(solapamiento S-NPP/MODIS) y para el conteo tras `FilterConfig` por defecto. La serie inversa estima conteos que habría registrado VIIRS por celda-mes, "
        "con incertidumbre; no ubica focos individuales.",
        "",
    ]
    return L
